const rules = $input.all().map(i => i.json).filter(r => r && r.pattern);
const ad = $('Receive Job Ad').first().json;
const policy = $('Set Screening Policy').first().json;
const text = String(ad.job_ad_text || '');
const lower = text.toLowerCase();
const hard = [];
const soft = [];
let rulePoints = 0;
for (const r of rules) {
  let matchedText = '';
  if (r.match_type === 'regex') {
    try {
      const m = text.match(new RegExp(r.pattern, 'i'));
      if (m) { matchedText = m[0]; }
    } catch (e) { continue; }
  } else {
    if (lower.includes(String(r.pattern).toLowerCase())) { matchedText = String(r.pattern); }
  }
  if (!matchedText) continue;
  const entry = { pattern: matchedText, ground: String(r.ground || ''), points: Number(r.points) || 0, note: String(r.note || '') };
  if (r.severity === 'hard') { hard.push(entry); } else { soft.push(entry); }
  rulePoints += entry.points;
}
const compact = lower.replace(/\s+/g, '');
const markers = ['(m/w/d)', '(w/m/d)', '(m/w/x)', '(d/m/w)', '(m/w)', '(w/m)', '(gn)', 'allgenders'];
let hasMarker = false;
for (const m of markers) {
  if (compact.includes(m)) { hasMarker = true; break; }
}
if (!hasMarker) {
  soft.push({ pattern: 'missing (m/w/d) marker', ground: 'gender', points: 15, note: 'German job ads should carry a gender-neutral marker such as (m/w/d) after the title.' });
  rulePoints += 15;
}
return [{ json: {
  job_title: String(ad.job_title || ''),
  ad_text: text,
  rules_loaded: rules.length,
  hard_flags: hard,
  soft_flags: soft,
  rule_points: rulePoints,
  review_threshold: Number(policy.review_threshold),
  model_max_points: Number(policy.model_max_points)
} }];

