parameters.jsCode:
const scan = $('Scan For Deterministic AGG Signals').first().json;
const first = $input.first();
const raw = first ? first.json : {};
const src = raw && typeof raw.output === 'object' && raw.output !== null ? raw.output : raw;
let modelFlags = [];
if (src && Array.isArray(src.flags)) { modelFlags = src.flags.filter(f => f && f.phrase); }
let modelNote = 'Groq reviewed the wording.';
let conf = Number(src ? src.confidence : NaN);
if (!Number.isFinite(conf)) { conf = 0; modelNote = 'The model did not return a readable answer; this verdict rests on the deterministic rules alone.'; }
if (conf > 0 && conf <= 1) { conf = Math.round(conf * 100); }
conf = Math.max(0, Math.min(100, Math.round(conf)));
const cap = Number.isFinite(Number(scan.model_max_points)) ? Number(scan.model_max_points) : 30;
const modelPoints = Math.min(cap, Math.round(modelFlags.length * 10 * (conf / 100)));
const rulePoints = Number(scan.rule_points) || 0;
const score = Math.min(100, rulePoints + modelPoints);
const threshold = Number.isFinite(Number(scan.review_threshold)) ? Number(scan.review_threshold) : 40;
const hard = Array.isArray(scan.hard_flags) ? scan.hard_flags : [];
const soft = Array.isArray(scan.soft_flags) ? scan.soft_flags : [];
let verdict = 'LIKELY CLEAR';
let refusalNote = '';
if (hard.length > 0) {
  verdict = 'VIOLATION RISK';
} else if (Number(scan.rules_loaded) === 0) {
  verdict = 'REVIEW';
  refusalNote = 'The AGG term table is empty, so nothing was actually checked. This screen refuses to answer clear without its reference rules.';
} else if (score >= threshold) {
  verdict = 'REVIEW';
}
const lines = [];
for (const f of hard) { lines.push('VIOLATION - ' + f.ground + ': "' + f.pattern + '". ' + f.note); }
for (const f of soft) { lines.push('review - ' + f.ground + ': "' + f.pattern + '". ' + f.note); }
for (const f of modelFlags) { lines.push('model - ' + (f.ground || 'unspecified') + ': "' + f.phrase + '". ' + (f.reason || '') + (f.rewrite ? ' Suggestion: ' + f.rewrite : '')); }
const flagLines = lines.length > 0 ? lines.join('\n') : 'No risky wording found by the rules or the model.';
const report = 'Rules matched ' + (hard.length + soft.length) + ' phrase(s) for ' + rulePoints + ' point(s); the model added ' + modelFlags.length + ' flag(s) for ' + modelPoints + ' capped point(s) at confidence ' + conf + '. ' + modelNote + (refusalNote ? ' ' + refusalNote : '');
return [{ json: {
  checked_at: new Date().toISOString(),
  job_title: String(scan.job_title || ''),
  verdict: verdict,
  risk_score: score,
  hard_flags: hard.map(f => f.pattern).join('; '),
  soft_flags: soft.map(f => f.pattern).join('; '),
  model_flags: modelFlags.map(f => f.phrase).join('; '),
  model_confidence: conf,
  review_threshold: threshold,
  flag_lines: flagLines,
  report: report
} }];

